  localparam logic [31:0] CSR_MIE_MEIX_MASK  = 32'h1 << CSR_MEIX_BIT;

  function automatic logic [31:0] pmp_csr_addr_to_cfg_idx(logic [11:0] csr_addr);
    logic [31:0] idx;
    unique case (csr_addr)
      12'h3A0: idx = 0;
      12'h3A1: idx = 1;
      12'h3A2: idx = 2;
      12'h3A3: idx = 3;
      default: idx = 0;
    endcase
    return idx;
  endfunction

endpackage

module ibex_csr #(
  parameter int unsigned    Width      = 32,
  parameter bit             ShadowCSR  = 1'b0,
  parameter logic [Width-1:0] ResetValue = '0
) (
  input  logic             clk_i,
  input  logic             rst_ni,
  input  logic             wr_en_i,
  input  logic [Width-1:0] wr_data_i,
  output logic [Width-1:0] rd_data_o,
  output logic             rd_error_o
);
  logic [Width-1:0] csr_q;

  assign rd_data_o = csr_q;

  always_ff @(posedge clk_i or negedge rst_ni) begin
    if (!rst_ni) begin
      csr_q <= ResetValue;
    end else if (wr_en_i) begin
      csr_q <= wr_data_i;
    end
  end

  assign rd_error_o = 1'b0;

endmodule

module ibex_counter #(
  parameter int unsigned CounterWidth = 32
) (
  input  logic             clk_i,
  input  logic             rst_ni,
  input  logic             counter_inc_i,
  input  logic             counterh_write_i,
  input  logic [31:0]      counter_val_i,
  output logic [63:0]      counter_val_o
);
  logic [63:0] counter;

  assign counter_val_o = counter;

  always_ff @(posedge clk_i or negedge rst_ni) begin
    if (!rst_ni) begin
      counter <= '0;
    end else if (counterh_write_i) begin
      counter[63:32] <= counter_val_i;
    end else if (counter_inc_i) begin
      counter <= counter + 64'd1;
    end
  end

endmodule

