  input  logic [31:0]                  csr_wdata_i,
  input  csr_op_e                      csr_op_i,
  input  logic                         csr_op_en_i,
  output logic [31:0]                  csr_rdata_o,

  input  logic                         irq_software_i,
  input  logic                         irq_timer_i,
  input  logic                         irq_external_i,
  input  logic [14:0]                  irq_fast_i,
  input  logic                         nmi_mode_i,
  output logic                         irq_pending_o,
  output irqs_t                        irqs_o,
  output logic                         csr_mstatus_mie_o,
  output logic                         csr_mstatus_tw_o,
  output logic [31:0]                  csr_mepc_o,
  output logic [31:0]                  csr_mtval_o,

  output pmp_cfg_t                     csr_pmp_cfg_o  [PMP_MAX_REGIONS],
  output logic [PMP_ADDR_MSB:0]        csr_pmp_addr_o [PMP_MAX_REGIONS],
  output pmp_mseccfg_t                 csr_pmp_mseccfg_o,

  output logic [31:0]                  csr_depc_o,
  input  logic                         debug_mode_i,
  input  logic                         debug_mode_entering_i,
  input  dbg_cause_e                   debug_cause_i,
  input  logic                         debug_csr_save_i,
  output logic                         debug_single_step_o,
  output logic                         debug_ebreakm_o,
  output logic                         debug_ebreaku_o,
  output logic                         trigger_match_o,

  input  logic [31:0]                  pc_if_i,
  input  logic [31:0]                  pc_id_i,
  input  logic [31:0]                  pc_wb_i,

  output logic                         data_ind_timing_o,
  output logic                         dummy_instr_en_o,
  output logic [2:0]                   dummy_instr_mask_o,
  output logic                         dummy_instr_seed_en_o,
  output logic [31:0]                  dummy_instr_seed_o,
  output logic                         icache_enable_o,
  output logic                         csr_shadow_err_o,
  input  logic                         ic_scr_key_valid_i,

  input  logic                         csr_save_if_i,
  input  logic                         csr_save_id_i,
  input  logic                         csr_save_wb_i,
  input  logic                         csr_restore_mret_i,
  input  logic                         csr_restore_dret_i,
  input  logic                         csr_save_cause_i,
  input  exc_cause_t                   csr_mcause_i,
  input  logic [31:0]                  csr_mtval_i,
  output logic                         illegal_csr_insn_o,
  output logic                         double_fault_seen_o,

  input  logic                         instr_ret_i,
  input  logic                         instr_ret_compressed_i,
  input  logic                         instr_ret_spec_i,
  input  logic                         instr_ret_compressed_spec_i,
  input  logic                         iside_wait_i,
  input  logic                         jump_i,
  input  logic                         branch_i,
  input  logic                         branch_taken_i,
  input  logic                         mem_load_i,
  input  logic                         mem_store_i,
  input  logic                         dside_wait_i,
  input  logic                         mul_wait_i,
  input  logic                         div_wait_i
);

  localparam int unsigned MHPMCounterNumOut = (MHPMCounterNum < 29) ? MHPMCounterNum : 29;
  localparam int unsigned NumPmpRegions = (PMPEnable && (PMPNumRegions > 0)) ? PMPNumRegions : 0;

  logic [31:0] csr_wdata_int;
  logic        csr_wr;

  logic [31:0] mstatus_q;
  logic [31:0] mie_q;
  logic [31:0] mtvec_q;
  logic [31:0] mepc_q;
  logic [31:0] mcause_q;
  logic [31:0] mtval_q;
  logic [31:0] mip_q;

  logic [31:0] mcountinhibit_q;
  logic [31:0] mhpmevent [32];

  logic [63:0] mhpmcounter [32];

  logic [31:0] dcsr_q;
  logic [31:0] depc_q;
  logic [31:0] mscratch_q;

  pmp_cfg_t    pmp_cfg_q [PMP_MAX_REGIONS];
  logic [PMP_ADDR_MSB:0] pmp_addr_q [PMP_MAX_REGIONS];
  pmp_mseccfg_t mseccfg_q;

  logic [31:0] cpuctrlsts_q;
  logic [31:0] secureseed_q;

  logic [31:0] tselect_q;
  logic [31:0] tdata1_q;
  logic [31:0] tdata2_q;
  logic [31:0] tdata3_q;

  logic illegal_csr;

  assign priv_mode_id_o  = PRIV_LVL_M;
  assign priv_mode_lsu_o = PRIV_LVL_M;
  assign csr_mstatus_tw_o = mstatus_q[21];

  logic unused_irq_timer;
  assign unused_irq_timer = irq_timer_i;

  always_comb begin
    csr_wdata_int = csr_wdata_i;
    csr_wr        = 1'b0;
    illegal_csr   = 1'b0;
    csr_rdata_o   = '0;

    if (csr_access_i && csr_op_en_i) begin
      unique case (csr_op_i)
        CSR_OP_READ: begin
          csr_wr = 1'b0;
        end
        CSR_OP_WRITE: begin
          csr_wdata_int = csr_wdata_i;
          csr_wr = 1'b1;
        end
        CSR_OP_SET: begin
          csr_wdata_int = csr_rdata_o | csr_wdata_i;
          csr_wr = 1'b1;
        end
        CSR_OP_CLEAR: begin
          csr_wdata_int = csr_rdata_o & ~csr_wdata_i;
          csr_wr = 1'b1;
        end
        default: ;
      endcase
    end

    unique case (csr_addr_i)
      CSR_MSTATUS: begin
        csr_rdata_o = mstatus_q;
      end
      CSR_MISA: begin
        csr_rdata_o = {CSR_MISA_MXL, 4'b0, 26'h0110804};
      end
      CSR_MIE: begin
        csr_rdata_o = mie_q;
      end
      CSR_MTVEC: begin
        csr_rdata_o = mtvec_q;
      end
      CSR_MCOUNTEREN: begin
        csr_rdata_o = '0;
      end
      CSR_MCOUNTINHIBIT: begin
        csr_rdata_o = mcountinhibit_q;
      end
      CSR_MSCRATCH: begin
        csr_rdata_o = mscratch_q;
      end
      CSR_MEPC: begin
        csr_rdata_o = mepc_q;
      end
      CSR_MCAUSE: begin
        csr_rdata_o = mcause_q;
      end
      CSR_MTVAL: begin
        csr_rdata_o = mtval_q;
      end
      CSR_MIP: begin
        csr_rdata_o = mip_q;
      end
      CSR_PMPCFG0, CSR_PMPCFG1, CSR_PMPCFG2, CSR_PMPCFG3: begin
        if (PMPEnable) begin
          logic [31:0] pmpcfg_rd;
          pmpcfg_rd = '0;
          automatic int unsigned base_idx;
          base_idx = int'(csr_addr_i) - int'(CSR_PMPCFG0);
          for (int unsigned i = 0; i < 4; i++) begin
            if ((base_idx * 4 + i) < PMPNumRegions) begin
              pmpcfg_rd[i*PMP_CFG_W +: PMP_CFG_W] = {
                pmp_cfg_q[base_idx*4+i].lock,
                2'b00,
                pmp_cfg_q[base_idx*4+i].mode,
                pmp_cfg_q[base_idx*4+i].exec,
                pmp_cfg_q[base_idx*4+i].write,
                pmp_cfg_q[base_idx*4+i].read
              };
            end
          end
          csr_rdata_o = pmpcfg_rd;
        end else begin
          illegal_csr = 1'b1;
        end
      end
      CSR_PMPADDR0:  begin if (PMPEnable) csr_rdata_o = pmp_addr_q[0][33:2];  else illegal_csr = 1'b1; end
      CSR_PMPADDR1:  begin if (PMPEnable) csr_rdata_o = pmp_addr_q[1][33:2];  else illegal_csr = 1'b1; end
      CSR_PMPADDR2:  begin if (PMPEnable) csr_rdata_o = pmp_addr_q[2][33:2];  else illegal_csr = 1'b1; end
      CSR_PMPADDR3:  begin if (PMPEnable) csr_rdata_o = pmp_addr_q[3][33:2];  else illegal_csr = 1'b1; end
      CSR_PMPADDR4:  begin if (PMPEnable && PMPNumRegions > 4) csr_rdata_o = pmp_addr_q[4][33:2];  else illegal_csr = 1'b1; end
      CSR_PMPADDR5:  begin if (PMPEnable && PMPNumRegions > 5) csr_rdata_o = pmp_addr_q[5][33:2];  else illegal_csr = 1'b1; end
      CSR_PMPADDR6:  begin if (PMPEnable && PMPNumRegions > 6) csr_rdata_o = pmp_addr_q[6][33:2];  else illegal_csr = 1'b1; end
      CSR_PMPADDR7:  begin if (PMPEnable && PMPNumRegions > 7) csr_rdata_o = pmp_addr_q[7][33:2];  else illegal_csr = 1'b1; end
      CSR_PMPADDR8:  begin if (PMPEnable && PMPNumRegions > 8) csr_rdata_o = pmp_addr_q[8][33:2];  else illegal_csr = 1'b1; end
      CSR_PMPADDR9:  begin if (PMPEnable && PMPNumRegions > 9) csr_rdata_o = pmp_addr_q[9][33:2];  else illegal_csr = 1'b1; end
      CSR_PMPADDR10: begin if (PMPEnable && PMPNumRegions > 10) csr_rdata_o = pmp_addr_q[10][33:2]; else illegal_csr = 1'b1; end
      CSR_PMPADDR11: begin if (PMPEnable && PMPNumRegions > 11) csr_rdata_o = pmp_addr_q[11][33:2]; else illegal_csr = 1'b1; end
      CSR_PMPADDR12: begin if (PMPEnable && PMPNumRegions > 12) csr_rdata_o = pmp_addr_q[12][33:2]; else illegal_csr = 1'b1; end
      CSR_PMPADDR13: begin if (PMPEnable && PMPNumRegions > 13) csr_rdata_o = pmp_addr_q[13][33:2]; else illegal_csr = 1'b1; end
      CSR_PMPADDR14: begin if (PMPEnable && PMPNumRegions > 14) csr_rdata_o = pmp_addr_q[14][33:2]; else illegal_csr = 1'b1; end
      CSR_PMPADDR15: begin if (PMPEnable && PMPNumRegions > 15) csr_rdata_o = pmp_addr_q[15][33:2]; else illegal_csr = 1'b1; end
      CSR_MSECCFG: begin
        if (PMPEnable) begin
          csr_rdata_o = {29'b0, mseccfg_q.mml, mseccfg_q.mmwp, mseccfg_q.rlb};
        end else begin
          illegal_csr = 1'b1;
        end
      end
      CSR_MSECCFGH: begin
        if (PMPEnable) begin
          csr_rdata_o = '0;
        end else begin
          illegal_csr = 1'b1;
        end
      end
      CSR_MCYCLE: begin
        csr_rdata_o = mhpmcounter[0][31:0];
      end
      CSR_MINSTRET: begin
        csr_rdata_o = mhpmcounter[2][31:0];
      end
      CSR_MCYCLEH: begin
        csr_rdata_o = mhpmcounter[0][63:32];
      end
      CSR_MINSTRETH: begin
        csr_rdata_o = mhpmcounter[2][63:32];
      end
      CSR_TSELECT: begin
        if (DbgTriggerEn) csr_rdata_o = tselect_q;
        else illegal_csr = 1'b1;
      end
      CSR_TDATA1: begin
        if (DbgTriggerEn) csr_rdata_o = tdata1_q;
        else illegal_csr = 1'b1;
      end
      CSR_TDATA2: begin
        if (DbgTriggerEn) csr_rdata_o = tdata2_q;
        else illegal_csr = 1'b1;
      end
      CSR_TDATA3: begin
        if (DbgTriggerEn) csr_rdata_o = tdata3_q;
        else illegal_csr = 1'b1;
      end
      CSR_TINFO: begin
        if (DbgTriggerEn) csr_rdata_o = 32'h1;
        else illegal_csr = 1'b1;
      end
      CSR_TCONTROL: begin
        if (DbgTriggerEn) csr_rdata_o = '0;
        else illegal_csr = 1'b1;
      end
      CSR_DCSR: begin
        if (debug_mode_i) csr_rdata_o = dcsr_q;
        else illegal_csr = 1'b1;
      end
      CSR_DPC: begin
        if (debug_mode_i) csr_rdata_o = depc_q;
        else illegal_csr = 1'b1;
      end
      CSR_DSCRATCH0: begin
        if (debug_mode_i) csr_rdata_o = '0;
        else illegal_csr = 1'b1;
      end
      CSR_DSCRATCH1: begin
        if (debug_mode_i) csr_rdata_o = '0;
        else illegal_csr = 1'b1;
      end
      CSR_CPUCTRLSTS: begin
        csr_rdata_o = cpuctrlsts_q;
      end
      CSR_SECURESEED: begin
        csr_rdata_o = secureseed_q;
      end
      CSR_MHARTID: begin
        csr_rdata_o = hart_id_i;
      end
      CSR_MVENDORID: begin
        csr_rdata_o = CsrMvendorId;
      end
      CSR_MARCHID: begin
        csr_rdata_o = CsrMimpId;
      end
      CSR_MIMPID: begin
        csr_rdata_o = CsrMimpId;
      end
      default: begin
        if (csr_addr_i >= CSR_MHPMEVENT3 && csr_addr_i <= CSR_MHPMEVENT31) begin
          automatic int unsigned idx;
          idx = int'(csr_addr_i) - int'(CSR_MHPMEVENT3) + 3;
          if (idx < (MHPMCounterNumOut + 3)) begin
            csr_rdata_o = mhpmevent[idx];
          end else begin
            illegal_csr = 1'b1;
          end
        end else if (csr_addr_i >= CSR_MHPMCOUNTER3 && csr_addr_i <= CSR_MHPMCOUNTER31) begin
          automatic int unsigned idx;
          idx = int'(csr_addr_i) - int'(CSR_MHPMCOUNTER3) + 3;
          if (idx < (MHPMCounterNumOut + 3)) begin
            csr_rdata_o = mhpmcounter[idx][31:0];
          end else begin
            illegal_csr = 1'b1;
          end
        end else if (csr_addr_i >= CSR_MHPMCOUNTER3H && csr_addr_i <= CSR_MHPMCOUNTER31H) begin
          automatic int unsigned idx;
          idx = int'(csr_addr_i) - int'(CSR_MHPMCOUNTER3H) + 3;
          if (idx < (MHPMCounterNumOut + 3)) begin
            csr_rdata_o = mhpmcounter[idx][63:32];
          end else begin
            illegal_csr = 1'b1;
          end
        end else begin
          illegal_csr = 1'b1;
        end
      end
    endcase
  end

  assign illegal_csr_insn_o = illegal_csr;

  logic [31:0] mstatus_d;
  always_comb begin
    mstatus_d = mstatus_q;
    if (csr_wr && csr_addr_i == CSR_MSTATUS) begin
      mstatus_d = csr_wdata_int;
      mstatus_d[12:11] = 2'b11;
      mstatus_d[17]    = 1'b0;
      mstatus_d[31:23] = '0;
      mstatus_d[7]     = 1'b0;
      mstatus_d[3]     = 1'b0;
      mstatus_d[19]    = csr_wdata_int[19];
    end
  end

  always_ff @(posedge clk_i or negedge rst_ni) begin
    if (!rst_ni) begin
      mstatus_q <= '0;
      mstatus_q[12:11] <= 2'b11;
    end else begin
      mstatus_q <= mstatus_d;
    end
  end

  logic [31:0] mie_d;
  always_comb begin
    mie_d = mie_q;
    if (csr_wr && csr_addr_i == CSR_MIE) begin
      mie_d = csr_wdata_int & (CSR_MIE_MSIX_MASK | CSR_MIE_MTIX_MASK |
                               CSR_MIE_MEIX_MASK | {{(16-15){1'b0}}, irq_fast_i});
    end
  end

  always_ff @(posedge clk_i or negedge rst_ni) begin
    if (!rst_ni) begin
      mie_q <= '0;
    end else begin
      mie_q <= mie_d;
    end
  end

  logic [31:0] mtvec_d;
  always_comb begin
    mtvec_d = mtvec_q;
    if (csr_mtvec_init_i) begin
      mtvec_d = {boot_addr_i[31:2], 1'b0, 1'b0};
    end else if (csr_wr && csr_addr_i == CSR_MTVEC) begin
      mtvec_d = {csr_wdata_int[31:2], 1'b0, csr_wdata_int[0]};
    end
  end

  always_ff @(posedge clk_i or negedge rst_ni) begin
    if (!rst_ni) begin
      mtvec_q <= '0;
    end else begin
      mtvec_q <= mtvec_d;
    end
  end

  assign csr_mtvec_o = mtvec_q;

  always_ff @(posedge clk_i or negedge rst_ni) begin
    if (!rst_ni) begin
      mscratch_q <= '0;
    end else if (csr_wr && csr_addr_i == CSR_MSCRATCH) begin
      mscratch_q <= csr_wdata_int;
    end
  end

  logic [31:0] mepc_d;
  always_comb begin
    mepc_d = mepc_q;
    if (csr_wr && csr_addr_i == CSR_MEPC) begin
      mepc_d = {csr_wdata_int[31:1], 1'b0};
    end else if (csr_save_cause_i) begin
      if (csr_save_if_i) mepc_d = {pc_if_i[31:1], 1'b0};
      else if (csr_save_id_i) mepc_d = {pc_id_i[31:1], 1'b0};
      else if (csr_save_wb_i) mepc_d = {pc_wb_i[31:1], 1'b0};
    end
  end

  always_ff @(posedge clk_i or negeg rst_ni) begin
    if (!rst_ni) begin
      mepc_q <= '0;
    end else begin
      mepc_q <= mepc_d;
    end
  end

  assign csr_mepc_o = mepc_q;

  always_ff @(posedge clk_i or negedge rst_ni) begin
    if (!rst_ni) begin
      mcause_q <= '0;
      mtval_q  <= '0;
    end else begin
      if (csr_save_cause_i) begin
        mcause_q <= {csr_mcause_i.irq, 25'b0, csr_mcause_i.code};
        mtval_q  <= csr_mtval_i;
      end else if (csr_wr && csr_addr_i == CSR_MCAUSE) begin
        mcause_q <= csr_wdata_int;
      end else if (csr_wr && csr_addr_i == CSR_MTVAL) begin
        mtval_q  <= csr_wdata_int;
      end
    end
  end

  assign csr_mtval_o = mtval_q;

  always_comb begin
    mip_q = '0;
    mip_q[CSR_MSIX_BIT]  = irq_software_i;
    mip_q[CSR_MTIX_BIT]  = irq_timer_i;
    mip_q[CSR_MEIX_BIT]  = irq_external_i;
    mip_q[CSR_MFIX_BIT_HIGH:CSR_MFIX_BIT_LOW] = irq_fast_i;
  end

  assign irqs_o.irq_software = mie_q[CSR_MSIX_BIT]  & mip_q[CSR_MSIX_BIT];
  assign irqs_o.irq_timer    = mie_q[CSR_MTIX_BIT]  & mip_q[CSR_MTIX_BIT];
  assign irqs_o.irq_external = mie_q[CSR_MEIX_BIT]  & mip_q[CSR_MEIX_BIT];
  assign irqs_o.irq_fast    = mie_q[CSR_MFIX_BIT_HIGH:CSR_MFIX_BIT_LOW] &
                               mip_q[CSR_MFIX_BIT_HIGH:CSR_MFIX_BIT_LOW];

  assign csr_mstatus_mie_o = mstatus_q[3];

  assign irq_pending_o = |{irqs_o.irq_software, irqs_o.irq_timer, irqs_o.irq_external,
                           irqs_o.irq_fast, irq_fast_i != '0};

  always_ff @(posedge clk_i or negedge rst_ni) begin
    if (!rst_ni) begin
      mstatus_q[3] <= 1'b0;
    end else if (csr_save_cause_i) begin
      mstatus_q[3] <= 1'b0;
    end else if (csr_restore_mret_i) begin
      mstatus_q[3] <= mstatus_q[7];
    end else if (csr_restore_dret_i) begin
      mstatus_q[3] <= mstatus_q[7];
    end
  end

  always_ff @(posedge clk_i or negedge rst_ni) begin
    if (!rst_ni) begin
      mstatus_q[7] <= 1'b0;
    end else if (csr_save_cause_i) begin
      mstatus_q[7] <= mstatus_q[3];
    end else if (csr_restore_mret_i) begin
      mstatus_q[7] <= 1'b1;
    end else if (csr_restore_dret_i) begin
      mstatus_q[7] <= 1'b1;
    end
  end

  always_ff @(posedge clk_i or negedge rst_ni) begin
    if (!rst_ni) begin
      mcountinhibit_q <= '0;
    end else if (csr_wr && csr_addr_i == CSR_MCOUNTINHIBIT) begin
      automatic logic [31:0] mask;
      mask = '1;
      mask[1] = 1'b0;
      for (int unsigned i = MHPMCounterNumOut + 3; i < 32; i++) begin
        mask[i] = 1'b0;
      end
      mcountinhibit_q <= csr_wdata_int & mask;
    end
  end

  for (genvar i = 3; i < 32; i++) begin : g_mhpmevent
    always_ff @(posedge clk_i or negedge rst_ni) begin
      if (!rst_ni) begin
        if (i < (MHPMCounterNumOut + 3)) begin
          mhpmevent[i] <= 32'(1 << (i - 3));
        end else begin
          mhpmevent[i] <= '0;
        end
      end else if (csr_wr && (csr_addr_i == csr_num_e'(int'(CSR_MHPMEVENT3) + (i - 3)))) begin
        if (i < (MHPMCounterNumOut + 3)) begin
          mhpmevent[i] <= csr_wdata_int;
        end
      end
    end
  end

  logic [31:0] mhpmcounter_write_val;
  logic        mhpmcounter_write;
  logic        mhpmcounterh_write;
  logic [63:0] mhpmcounter_mask;

  always_comb begin
    if (MHPMCounterWidth >= 64) begin
      mhpmcounter_mask = 64'hFFFFFFFFFFFFFFFF;
    end else begin
      mhpmcounter_mask = (64'h1 << MHPMCounterWidth) - 1;
    end
  end

  logic [31:0] pmp_cfg_wr_data;
  logic [31:0] pmp_addr_wr_data;

  for (genvar i = 0; i < 32; i++) begin : g_mhpmcounter
    logic counter_inc;
    logic [63:0] counter_d;
    logic counter_write_low;
    logic counter_write_high;

    always_comb begin
      counter_inc = 1'b0;
      if (i == 0) begin
        counter_inc = ~mcountinhibit_q[0];
      end else if (i == 2) begin
        counter_inc = ~mcountinhibit_q[2] & instr_ret_i;
      end else if (i >= 3 && i < (MHPMCounterNumOut + 3)) begin
        counter_inc = ~mcountinhibit_q[i] & instr_ret_i;
      end
    end

    assign counter_write_low  = csr_wr && (csr_addr_i == csr_num_e'(int'(CSR_MCYCLE) + i)) &&
                                 (i < (MHPMCounterNumOut + 3) || i == 0 || i == 2);
    assign counter_write_high = csr_wr && (csr_addr_i == csr_num_e'(int'(CSR_MCYCLEH) + i)) &&
                                 (i < (MHPMCounterNumOut + 3) || i == 0 || i == 2);

    always_comb begin
      counter_d = mhpmcounter[i];
      if (counter_write_low) begin
        counter_d[31:0] = csr_wdata_int;
      end else if (counter_write_high) begin
        counter_d[63:32] = csr_wdata_int;
      end else if (counter_inc) begin
        counter_d = mhpmcounter[i] + 64'd1;
      end
      if (i >= 3 && i < (MHPMCounterNumOut + 3)) begin
        counter_d = counter_d & mhpmcounter_mask;
      end
    end

    always_ff @(posedge clk_i or negedge rst_ni) begin
      if (!rst_ni) begin
        mhpmcounter[i] <= '0;
      end else begin
        mhpmcounter[i] <= counter_d;
      end
    end
  end

  for (genvar i = 0; i < PMP_MAX_REGIONS; i++) begin : g_pmp
    always_ff @(posedge clk_i or negedge rst_ni) begin
      if (!rst_ni) begin
        pmp_cfg_q[i] <= PMPRstCfg[i];
        pmp_addr_q[i] <= PMPRstAddr[i];
      end else begin
        if (csr_wr && PMPEnable && (i < PMPNumRegions)) begin
          automatic int unsigned cfg_idx;
          cfg_idx = i / 4;
          if (csr_addr_i == csr_num_e'(int'(CSR_PMPCFG0) + cfg_idx)) begin
            automatic logic [7:0] cfg_byte;
            cfg_byte = csr_wdata_int[(i%4)*PMP_CFG_W +: PMP_CFG_W];
            if (!pmp_cfg_q[i].lock && !mseccfg_q.rlb) begin
              pmp_cfg_q[i].lock  <= cfg_byte[7];
              pmp_cfg_q[i].mode  <= cfg_byte[4:3];
              pmp_cfg_q[i].exec  <= cfg_byte[2];
              pmp_cfg_q[i].write <= cfg_byte[1];
              pmp_cfg_q[i].read  <= cfg_byte[0];
            end
          end
          if (csr_addr_i == csr_num_e'(int'(CSR_PMPADDR0) + i)) begin
            if (!pmp_cfg_q[i].lock) begin
              pmp_addr_q[i] <= {csr_wdata_int[29:0], 2'b00};
            end
          end
        end
      end
    end
  end

  for (genvar i = 0; i < PMP_MAX_REGIONS; i++) begin : g_pmp_output
    assign csr_pmp_cfg_o[i]  = pmp_cfg_q[i];
    assign csr_pmp_addr_o[i] = pmp_addr_q[i];
  end

  always_ff @(posedge clk_i or negedge rst_ni) begin
    if (!rst_ni) begin
      mseccfg_q <= PMPRstMsecCfg;
    end else if (csr_wr && PMPEnable && csr_addr_i == CSR_MSECCFG) begin
      if (!mseccfg_q.rlb) begin
        mseccfg_q.rlb <= csr_wdata_int[0];
      end
      mseccfg_q.mmwp <= csr_wdata_int[1] | mseccfg_q.mmwp;
      mseccfg_q.mml  <= csr_wdata_int[2] | mseccfg_q.mml;
    end
  end

  assign csr_pmp_mseccfg_o = mseccfg_q;

  always_ff @(posedge clk_i or negedge rst_ni) begin
    if (!rst_ni) begin
      dcsr_q <= 32'h4000;
    end else if (debug_mode_i) begin
      if (csr_wr && csr_addr_i == CSR_DCSR) begin
        dcsr_q[31:28] <= csr_wdata_int[31:28];
        dcsr_q[17]    <= 1'b0;
        dcsr_q[16:15] <= csr_wdata_int[16:15];
        dcsr_q[14:12] <= 3'h4;
        dcsr_q[11]    <= csr_wdata_int[11];
        dcsr_q[10]    <= csr_wdata_int[10];
        dcsr_q[9]     <= csr_wdata_int[9];
        dcsr_q[8]     <= csr_wdata_int[8];
        dcsr_q[7:6]   <= 2'b00;
        dcsr_q[5:4]   <= csr_wdata_int[5:4];
        dcsr_q[3:0]   <= csr_wdata_int[3:0];
      end
    end
  end

  always_ff @(posedge clk_i or negedge rst_ni) begin
    if (!rst_ni) begin
      depc_q <= '0;
    end else if (debug_csr_save_i) begin
      depc_q <= {pc_id_i[31:1], 1'b0};
    end else if (debug_mode_i && csr_wr && csr_addr_i == CSR_DPC) begin
      depc_q <= {csr_wdata_int[31:1], 1'b0};
    end
  end

  assign csr_depc_o = depc_q;
  assign debug_single_step_o = dcsr_q[2];
  assign debug_ebreakm_o = dcsr_q[15];
  assign debug_ebreaku_o = dcsr_q[12];

  always_ff @(posedge clk_i or negedge rst_ni) begin
    if (!rst_ni) begin
      tselect_q <= '0;
      tdata1_q  <= '0;
      tdata2_q  <= '0;
      tdata3_q  <= '0;
    end else if (DbgTriggerEn && debug_mode_i) begin
      if (csr_wr && csr_addr_i == CSR_TSELECT) tselect_q <= csr_wdata_int;
      if (csr_wr && csr_addr_i == CSR_TDATA1)  tdata1_q  <= csr_wdata_int;
      if (csr_wr && csr_addr_i == CSR_TDATA2)  tdata2_q  <= csr_wdata_int;
      if (csr_wr && csr_addr_i == CSR_TDATA3)  tdata3_q  <= csr_wdata_int;
    end
  end

  assign trigger_match_o = 1'b0;

  always_ff @(posedge clk_i or negedge rst_ni) begin
    if (!rst_ni) begin
      cpuctrlsts_q <= '0;
    end else if (csr_wr && csr_addr_i == CSR_CPUCTRLSTS) begin
      if (ICache) cpuctrlsts_q[0] <= csr_wdata_int[0];
      if (DataIndTiming) cpuctrlsts_q[1] <= csr_wdata_int[1];
      if (DummyInstructions) cpuctrlsts_q[2] <= csr_wdata_int[2];
      cpuctrlsts_q[5:3] <= csr_wdata_int[5:3];
    end
  end

  assign icache_enable_o   = ICache ? cpuctrlsts_q[0] : 1'b0;
  assign data_ind_timing_o = DataIndTiming ? cpuctrlsts_q[1] : 1'b0;
  assign dummy_instr_en_o  = DummyInstructions ? cpuctrlsts_q[2] : 1'b0;
  assign dummy_instr_mask_o = cpuctrlsts_q[5:3];
  assign dummy_instr_seed_en_o = 1'b0;
  assign dummy_instr_seed_o = '0;

  always_ff @(posedge clk_i or negedge rst_ni) begin
    if (!rst_ni) begin
      secureseed_q <= '0;
    end else if (csr_wr && csr_addr_i == CSR_SECURESEED) begin
      secureseed_q <= csr_wdata_int;
    end
  end

  assign csr_shadow_err_o = 1'b0;
  assign double_fault_seen_o = 1'b0;

  logic cpuctrlsts_ic_scr_key_valid_q;
  always_ff @(posedge clk_i or negedge rst_ni) begin
    if (!rst_ni) begin
      cpuctrlsts_ic_scr_key_valid_q <= 1'b0;
    end else begin
      cpuctrlsts_ic_scr_key_valid_q <= ic_scr_key_valid_i;
    end
  end

endmodule

arguments.newString:
typedef enum logic [2:0] {
  DBG_CAUSE_NONE,
  DBG_CAUSE_EBREAK,
  DBG_CAUSE_TRIGGER,
  DBG_CAUSE_HALTREQ,
  DBG_CAUSE_STEP
} dbg_cause_e;

function automatic logic [31:0] pmp_csr_addr_to_cfg_idx(logic [11:0] csr_addr);

arguments.content:
module ibex_cs_registers import ibex_pkg::*; #(
  parameter bit               DbgTriggerEn      = 1'b0,
  parameter int unsigned       DbgHwBreakNum     = 1,
  parameter bit               DataIndTiming     = 1'b0,
  parameter bit               DummyInstructions = 1'b0,
  parameter bit               ShadowCSR         = 1'b0,
  parameter bit               ICache            = 1'b0,
  parameter int unsigned       MHPMCounterNum    = 0,
  parameter int unsigned       MHPMCounterWidth  = 40,
  parameter bit               PMPEnable         = 1'b0,
  parameter int unsigned       PMPGranularity    = 0,
  parameter int unsigned       PMPNumRegions     = 4,
  parameter pmp_cfg_t         PMPRstCfg [PMP_MAX_REGIONS] = PmpCfgRst,
  parameter logic [PMP_ADDR_MSB:0] PMPRstAddr [PMP_MAX_REGIONS] = PmpAddrRst,
  parameter pmp_mseccfg_t    PMPRstMsecCfg     = PmpMseccfgRst,
  parameter bit               RV32E             = 1'b0,
  parameter rv32m_e           RV32M             = RV32MFast,
  parameter rv32b_e           RV32B             = RV32BNone,
  parameter logic [31:0]      CsrMvendorId       = 32'b0,
  parameter logic [31:0]      CsrMimpId         = 32'b0
) (
  input  logic                         clk_i,
  input  logic                         rst_ni,
  input  logic [31:0]                  hart_id_i,
  output priv_lvl_e                    priv_mode_id_o,
  output priv_lvl_e                    priv_mode_lsu_o,
  output logic [31:0]                  csr_mtvec_o,
  input  logic                         csr_mtvec_init_i,
  input  logic [31:0]                  boot_addr_i,
  input  logic                         csr_access_i,
  input  csr_num_e                     csr_addr_i,
  input  logic [31:0]                  csr_wdata_i,
  input  csr_op_e                      csr_op_i,
  input  logic                         csr_op_en_i,
  output logic [31:0]                  csr_rdata_o,
  input  logic                         irq_software_i,
  input  logic                         irq_timer_i,
  input  logic                         irq_external_i,
  input  logic [14:0]                  irq_fast_i,
  input  logic                         nmi_mode_i,
  output logic                         irq_pending_o,
  output irqs_t                        irqs_o,
  output logic                         csr_mstatus_mie_o,
  output logic                         csr_mstatus_tw_o,
  output logic [31:0]                  csr_mepc_o,
  output logic [31:0]                  csr_mtval_o,
  output pmp_cfg_t                     csr_pmp_cfg_o  [PMP_MAX_REGIONS],
  output logic [PMP_ADDR_MSB:0]        csr_pmp_addr_o [PMP_MAX_REGIONS],
  output pmp_mseccfg_t                 csr_pmp_mseccfg_o,
  output logic [31:0]                  csr_depc_o,
  input  logic                         debug_mode_i,
  input  logic                         debug_mode_entering_i,
  input  dbg_cause_e                   debug_cause_i,
  input  logic                         debug_csr_save_i,
  output logic                         debug_single_step_o,
  output logic                         debug_ebreakm_o,
  output logic                         debug_ebreaku_o,
  output logic                         trigger_match_o,
  input  logic [31:0]                  pc_if_i,
  input  logic [31:0]                  pc_id_i,
  input  logic [31:0]                  pc_wb_i,
  output logic                         data_ind_timing_o,
  output logic                         dummy_instr_en_o,
  output logic [2:0]                   dummy_instr_mask_o,
  output logic                         dummy_instr_seed_en_o,
  output logic [31:0]                  dummy_instr_seed_o,
  output logic                         icache_enable_o,
  output logic                         csr_shadow_err_o,
  input  logic                         ic_scr_key_valid_i,
  input  logic                         csr_save_if_i,
  input  logic                         csr_save_id_i,
  input  logic                         csr_save_wb_i,
  input  logic                         csr_restore_mret_i,
  input  logic                         csr_restore_dret_i,
  input  logic                         csr_save_cause_i,
  input  exc_cause_t                   csr_mcause_i,
  input  logic [31:0]                  csr_mtval_i,
  output logic                         illegal_csr_insn_o,
  output logic                         double_fault_seen_o,
  input  logic                         instr_ret_i,
  input  logic                         instr_ret_compressed_i,
  input  logic                         instr_ret_spec_i,
  input  logic                         instr_ret_compressed_spec_i,
  input  logic                         iside_wait_i,
  input  logic                         jump_i,
  input  logic                         branch_i,
  input  logic                         branch_taken_i,
  input  logic                         mem_load_i,
  input  logic                         mem_store_i,
  input  logic                         dside_wait_i,
  input  logic                         mul_wait_i,
  input  logic                         div_wait_i
);

  localparam int unsigned MHPMCounterNumOut = (MHPMCounterNum < 29) ? MHPMCounterNum : 29;

  logic [31:0] csr_wdata_int;
  logic        csr_wr;
  logic [31:0] mstatus_q;
  logic [31:0] mie_q;
  logic [31:0] mtvec_q;
  logic [31:0] mepc_q;
  logic [31:0] mcause_q;
  logic [31:0] mtval_q;
  logic [31:0] mip_q;
  logic [31:0] mcountinhibit_q;
  logic [31:0] mhpmevent_q [32];
  logic [63:0] mhpmcounter_q [32];
  logic [31:0] dcsr_q;
  logic [31:0] depc_q;
  logic [31:0] mscratch_q;
  pmp_cfg_t    pmp_cfg_q [PMP_MAX_REGIONS];
  logic [PMP_ADDR_MSB:0] pmp_addr_q [PMP_MAX_REGIONS];
  pmp_mseccfg_t mseccfg_q;
  logic [31:0] cpuctrlsts_q;
  logic [31:0] secureseed_q;
  logic [31:0] tselect_q;
  logic [31:0] tdata1_q;
  logic [31:0] tdata2_q;
  logic [31:0] tdata3_q;
  logic illegal_csr;
  logic [63:0] mhpmcounter_mask;

  assign priv_mode_id_o  = PRIV_LVL_M;
  assign priv_mode_lsu_o = PRIV_LVL_M;

  always_comb begin
    if (MHPMCounterWidth >= 64)
      mhpmcounter_mask = 64'hFFFFFFFFFFFFFFFF;
    else
      mhpmcounter_mask = (64'h1 << MHPMCounterWidth) - 1;
  end

  always_comb begin
    csr_wdata_int = csr_wdata_i;
    csr_wr        = 1'b0;
    illegal_csr   = 1'b0;
    csr_rdata_o   = '0;
    if (csr_access_i && csr_op_en_i) begin
      unique case (csr_op_i)
        CSR_OP_READ:  csr_wr = 1'b0;
        CSR_OP_WRITE: begin csr_wdata_int = csr_wdata_i; csr_wr = 1'b1; end
        CSR_OP_SET:   begin csr_wdata_int = csr_rdata_o | csr_wdata_i; csr_wr = 1'b1; end
        CSR_OP_CLEAR: begin csr_wdata_int = csr_rdata_o & ~csr_wdata_i; csr_wr = 1'b1; end
        default: ;
      endcase
    end
    unique case (csr_addr_i)
      CSR_MSTATUS:      csr_rdata_o = mstatus_q;
      CSR_MISA:          csr_rdata_o = {CSR_MISA_MXL, 4'b0, 26'h0110804};
      CSR_MIE:           csr_rdata_o = mie_q;
      CSR_MTVEC:         csr_rdata_o = mtvec_q;
      CSR_MCOUNTEREN:    csr_rdata_o = '0;
      CSR_MCOUNTINHIBIT: csr_rdata_o = mcountinhibit_q;
      CSR_MSCRATCH:      csr_rdata_o = mscratch_q;
      CSR_MEPC:          csr_rdata_o = mepc_q;
      CSR_MCAUSE:        csr_rdata_o = mcause_q;
      CSR_MTVAL:         csr_rdata_o = mtval_q;
      CSR_MIP:           csr_rdata_o = mip_q;
      CSR_MSECCFG: begin
        if (PMPEnable) csr_rdata_o = {29'b0, mseccfg_q.mml, mseccfg_q.mmwp, mseccfg_q.rlb};
        else illegal_csr = 1'b1;
      end
      CSR_MSECCFGH: begin
        if (PMPEnable) csr_rdata_o = '0;
        else illegal_csr = 1'b1;
      end
      CSR_PMPCFG0, CSR_PMPCFG1, CSR_PMPCFG2, CSR_PMPCFG3: begin
        if (PMPEnable) begin
          automatic int unsigned base_idx = int'(csr_addr_i) - int'(CSR_PMPCFG0);
          automatic logic [31:0] pmpcfg_rd = '0;
          for (int unsigned i = 0; i < 4; i++) begin
            if ((base_idx * 4 + i) < PMPNumRegions) begin
              pmpcfg_rd[i*PMP_CFG_W +: PMP_CFG_W] = {
                pmp_cfg_q[base_idx*4+i].lock, 2'b00,
                pmp_cfg_q[base_idx*4+i].mode,
                pmp_cfg_q[base_idx*4+i].exec,
                pmp_cfg_q[base_idx*4+i].write,
                pmp_cfg_q[base_idx*4+i].read
              };
            end
          end
          csr_rdata_o = pmpcfg_rd;
        end else begin
          illegal_csr = 1'b1;
        end
      end
      CSR_PMPADDR0:  begin if (PMPEnable && 0 < PMPNumRegions) csr_rdata_o = pmp_addr_q[0][33:2];  else illegal_csr = 1'b1; end
      CSR_PMPADDR1:  begin if (PMPEnable && 1 < PMPNumRegions) csr_rdata_o = pmp_addr_q[1][33:2];  else illegal_csr = 1'b1; end
      CSR_PMPADDR2:  begin if (PMPEnable && 2 < PMPNumRegions) csr_rdata_o = pmp_addr_q[2][33:2];  else illegal_csr = 1'b1; end
      CSR_PMPADDR3:  begin if (PMPEnable && 3 < PMPNumRegions) csr_rdata_o = pmp_addr_q[3][33:2];  else illegal_csr = 1'b1; end
      CSR_PMPADDR4:  begin if (PMPEnable && 4 < PMPNumRegions) csr_rdata_o = pmp_addr_q[4][33:2];  else illegal_csr = 1'b1; end
      CSR_PMPADDR5:  begin if (PMPEnable && 5 < PMPNumRegions) csr_rdata_o = pmp_addr_q[5][33:2];  else illegal_csr = 1'b1; end
      CSR_PMPADDR6:  begin if (PMPEnable && 6 < PMPNumRegions) csr_rdata_o = pmp_addr_q[6][33:2];  else illegal_csr = 1'b1; end
      CSR_PMPADDR7:  begin if (PMPEnable && 7 < PMPNumRegions) csr_rdata_o = pmp_addr_q[7][33:2];  else illegal_csr = 1'b1; end
      CSR_PMPADDR8:  begin if (PMPEnable && 8 < PMPNumRegions) csr_rdata_o = pmp_addr_q[8][33:2];  else illegal_csr = 1'b1; end
      CSR_PMPADDR9:  begin if (PMPEnable && 9 < PMPNumRegions) csr_rdata_o = pmp_addr_q[9][33:2];  else illegal_csr = 1'b1; end
      CSR_PMPADDR10: begin if (PMPEnable && 10 < PMPNumRegions) csr_rdata_o = pmp_addr_q[10][33:2]; else illegal_csr = 1'b1; end
      CSR_PMPADDR11: begin if (PMPEnable && 11 < PMPNumRegions) csr_rdata_o = pmp_addr_q[11][33:2]; else illegal_csr = 1'b1; end
      CSR_PMPADDR12: begin if (PMPEnable && 12 < PMPNumRegions) csr_rdata_o = pmp_addr_q[12][33:2]; else illegal_csr = 1'b1; end
      CSR_PMPADDR13: begin if (PMPEnable && 13 < PMPNumRegions) csr_rdata_o = pmp_addr_q[13][33:2]; else illegal_csr = 1'b1; end
      CSR_PMPADDR14: begin if (PMPEnable && 14 < PMPNumRegions) csr_rdata_o = pmp_addr_q[14][33:2]; else illegal_csr = 1'b1; end
      CSR_PMPADDR15: begin if (PMPEnable && 15 < PMPNumRegions) csr_rdata_o = pmp_addr_q[15][33:2]; else illegal_csr = 1'b1; end
      CSR_MCYCLE:    csr_rdata_o = mhpmcounter_q[0][31:0];
      CSR_MINSTRET:  csr_rdata_o = mhpmcounter_q[2][31:0];
      CSR_MCYCLEH:   csr_rdata_o = mhpmcounter_q[0][63:32];
      CSR_MINSTRETH: csr_rdata_o = mhpmcounter_q[2][63:32];
      CSR_TSELECT: begin if (DbgTriggerEn) csr_rdata_o = tselect_q; else illegal_csr = 1'b1; end
      CSR_TDATA1:   begin if (DbgTriggerEn) csr_rdata_o = tdata1_q;  else illegal_csr = 1'b1; end
      CSR_TDATA2:   begin if (DbgTriggerEn) csr_rdata_o = tdata2_q;  else illegal_csr = 1'b1; end
      CSR_TDATA3:   begin if (DbgTriggerEn) csr_rdata_o = tdata3_q;  else illegal_csr = 1'b1; end
      CSR_TINFO:    begin if (DbgTriggerEn) csr_rdata_o = 32'h1;      else illegal_csr = 1'b1; end
      CSR_TCONTROL: begin if (DbgTriggerEn) csr_rdata_o = '0;        else illegal_csr = 1'b1; end
      CSR_DCSR:      begin if (debug_mode_i) csr_rdata_o = dcsr_q;  else illegal_csr = 1'b1; end
      CSR_DPC:       begin if (debug_mode_i) csr_rdata_o = depc_q;  else illegal_csr = 1'b1; end
      CSR_DSCRATCH0: begin if (debug_mode_i) csr_rdata_o = '0;       else illegal_csr = 1'b1; end
      CSR_DSCRATCH1: begin if (debug_mode_i) csr_rdata_o = '0;       else illegal_csr = 1'b1; end
      CSR_CPUCTRLSTS: csr_rdata_o = cpuctrlsts_q;
      CSR_SECURESEED: csr_rdata_o = secureseed_q;
      CSR_MHARTID:   csr_rdata_o = hart_id_i;
      CSR_MVENDORID: csr_rdata_o = CsrMvendorId;
      CSR_MARCHID:   csr_rdata_o = CsrMimpId;
      CSR_MIMPID:    csr_rdata_o = CsrMimpId;
      default: begin
        if (csr_addr_i >= CSR_MHPMEVENT3 && csr_addr_i <= CSR_MHPMEVENT31) begin
          automatic int unsigned idx = int'(csr_addr_i) - int'(CSR_MHPMEVENT3) + 3;
          if (idx < (MHPMCounterNumOut + 3))
            csr_rdata_o = mhpmevent_q[idx];
          else
            illegal_csr = 1'b1;
        end else if (csr_addr_i >= CSR_MHPMCOUNTER3 && csr_addr_i <= CSR_MHPMCOUNTER31) begin
          automatic int unsigned idx = int'(csr_addr_i) - int'(CSR_MHPMCOUNTER3) + 3;
          if (idx < (MHPMCounterNumOut + 3))
            csr_rdata_o = mhpmcounter_q[idx][31:0];
          else
            illegal_csr = 1'b1;
        end else if (csr_addr_i >= CSR_MHPMCOUNTER3H && csr_addr_i <= CSR_MHPMCOUNTER31H) begin
          automatic int unsigned idx = int'(csr_addr_i) - int'(CSR_MHPMCOUNTER3H) + 3;
          if (idx < (MHPMCounterNumOut + 3))
            csr_rdata_o = mhpmcounter_q[idx][63:32];
          else
            illegal_csr = 1'b1;
        end else begin
          illegal_csr = 1'b1;
        end
      end
    endcase
  end

  assign illegal_csr_insn_o = illegal_csr;

  // MSTATUS
  always_ff @(posedge clk_i or negedge rst_ni) begin
    if (!rst_ni) begin
      mstatus_q <= '0;
      mstatus_q[12:11] <= 2'b11;
    end else begin
      if (csr_save_cause_i) begin
        mstatus_q[7] <= mstatus_q[3];
        mstatus_q[3] <= 1'b0;
      end else if (csr_restore_mret_i || csr_restore_dret_i) begin
        mstatus_q[3] <= mstatus_q[7];
        mstatus_q[7] <= 1'b1;
      end else if (csr_wr && csr_addr_i == CSR_MSTATUS) begin
        mstatus_q <= csr_wdata_int;
        mstatus_q[12:11] <= 2'b11;
        mstatus_q[17]    <= 1'b0;
        mstatus_q[31:23] <= '0;
        mstatus_q[7]     <= 1'b0;
        mstatus_q[3]     <= 1'b0;
        mstatus_q[19]    <= csr_wdata_int[19];
      end
    end
  end

  assign csr_mstatus_mie_o = mstatus_q[3];
  assign csr_mstatus_tw_o  = mstatus_q[21];

  // MIE
  always_ff @(posedge clk_i or negedge rst_ni) begin
    if (!rst_ni) begin
      mie_q <= '0;
    end else if (csr_wr && csr_addr_i == CSR_MIE) begin
      mie_q <= csr_wdata_int & (CSR_MIE_MSIX_MASK | CSR_MIE_MTIX_MASK |
                                 CSR_MIE_MEIX_MASK | {17'b0, irq_fast_i});
    end
  end

  // MTVEC
  always_ff @(posedge clk_i or negedge rst_ni) begin
    if (!rst_ni) begin
      mtvec_q <= '0;
    end else if (csr_mtvec_init_i) begin
      mtvec_q <= {boot_addr_i[31:2], 2'b00};
    end else if (csr_wr && csr_addr_i == CSR_MTVEC) begin
      mtvec_q <= {csr_wdata_int[31:2], 1'b0, csr_wdata_int[0]};
    end
  end
  assign csr_mtvec_o = mtvec_q;

  // MSCRATCH
  always_ff @(posedge clk_i or negedge rst_ni) begin
    if (!rst_ni) mscratch_q <= '0;
    else if (csr_wr && csr_addr_i == CSR_MSCRATCH) mscratch_q <= csr_wdata_int;
  end

  // MEPC
  always_ff @(posedge clk_i or negedge rst_ni) begin
    if (!rst_ni) begin
      mepc_q <= '0;
    end else if (csr_wr && csr_addr_i == CSR_MEPC) begin
      mepc_q <= {csr_wdata_int[31:1], 1'b0};
    end else if (csr_save_cause_i) begin
      if (csr_save_if_i)       mepc_q <= {pc_if_i[31:1], 1'b0};
      else if (csr_save_id_i)  mepc_q <= {pc_id_i[31:1], 1'b0};
      else if (csr_save_wb_i)  mepc_q <= {pc_wb_i[31:1], 1'b0};
    end
  end
  assign csr_mepc_o = mepc_q;

  // MCAUSE / MTVAL
  always_ff @(posedge clk_i or negedge rst_ni) begin
    if (!rst_ni) begin
      mcause_q <= '0;
      mtval_q  <= '0;
    end else begin
      if (csr_save_cause_i) begin
        mcause_q <= {csr_mcause_i.irq, 25'b0, csr_mcause_i.code};
        mtval_q  <= csr_mtval_i;
      end else begin
        if (csr_wr && csr_addr_i == CSR_MCAUSE) mcause_q <= csr_wdata_int;
        if (csr_wr && csr_addr_i == CSR_MTVAL)  mtval_q  <= csr_wdata_int;
      end
    end
  end
  assign csr_mtval_o = mtval_q;

  // MIP (read-only from software perspective, driven by irq inputs)
  always_comb begin
    mip_q = '0;
    mip_q[CSR_MSIX_BIT]  = irq_software_i;
    mip_q[CSR_MTIX_BIT]  = irq_timer_i;
    mip_q[CSR_MEIX_BIT]  = irq_external_i;
    mip_q[CSR_MFIX_BIT_HIGH:CSR_MFIX_BIT_LOW] = irq_fast_i;
  end

  // IRQ outputs
  assign irqs_o.irq_software = mie_q[CSR_MSIX_BIT]  & mip_q[CSR_MSIX_BIT];
  assign irqs_o.irq_timer    = mie_q[CSR_MTIX_BIT]  & mip_q[CSR_MTIX_BIT];
  assign irqs_o.irq_external = mie_q[CSR_MEIX_BIT]  & mip_q[CSR_MEIX_BIT];
  assign irqs_o.irq_fast     = mie_q[CSR_MFIX_BIT_HIGH:CSR_MFIX_BIT_LOW] &
                                mip_q[CSR_MFIX_BIT_HIGH:CSR_MFIX_BIT_LOW];

  assign irq_pending_o = |{irqs_o.irq_software, irqs_o.irq_timer, irqs_o.irq_external,
                           irqs_o.irq_fast};

  // MCOUNTINHIBIT
  always_ff @(posedge clk_i or negedge rst_ni) begin
    if (!rst_ni) begin
      mcountinhibit_q <= '0;
    end else if (csr_wr && csr_addr_i == CSR_MCOUNTINHIBIT) begin
      automatic logic [31:0] mask = '1;
      mask[1] = 1'b0;
      for (int unsigned i = MHPMCounterNumOut + 3; i < 32; i++) mask[i] = 1'b0;
      mcountinhibit_q <= csr_wdata_int & mask;
    end
  end

  // MHPMEVENT
  for (genvar i = 3; i < 32; i++) begin : g_mhpmevent
    always_ff @(posedge clk_i or negedge rst_ni) begin
      if (!rst_ni) begin
        if (i < (MHPMCounterNumOut + 3))
          mhpmevent_q[i] <= 32'(1 << (i - 3));
        else
          mhpmevent_q[i] <= '0;
      end else if (csr_wr && csr_addr_i == csr_num_e'(int'(CSR_MHPMEVENT3) + (i - 3))) begin
        if (i < (MHPMCounterNumOut + 3))
          mhpmevent_q[i] <= csr_wdata_int;
      end
    end
  end

  // MHPMCOUNTER
  for (genvar i = 0; i < 32; i++) begin : g_mhpmcounter
    logic        counter_inc;
    logic [63:0] counter_d;
    logic        counter_write_low;
    logic        counter_write_high;

    always_comb begin
      counter_inc = 1'b0;
      if (i == 0)
        counter_inc = ~mcountinhibit_q[0];
      else if (i == 2)
        counter_inc = ~mcountinhibit_q[2] & instr_ret_i;
      else if (i >= 3 && i < (MHPMCounterNumOut + 3))
        counter_inc = ~mcountinhibit_q[i] & instr_ret_i;
    end

    assign counter_write_low  = csr_wr && (csr_addr_i == csr_num_e'(int'(CSR_MCYCLE) + i)) &&
                                  (i == 0 || i == 2 || (i >= 3 && i < (MHPMCounterNumOut + 3)));
    assign counter_write_high = csr_wr && (csr_addr_i == csr_num_e'(int'(CSR_MCYCLEH) + i)) &&
                                  (i == 0 || i == 2 || (i >= 3 && i < (MHPMCounterNumOut + 3)));

    always_comb begin
      counter_d = mhpmcounter_q[i];
      if (counter_write_low)
        counter_d[31:0] = csr_wdata_int;
      else if (counter_write_high)
        counter_d[63:32] = csr_wdata_int;
      else if (counter_inc)
        counter_d = mhpmcounter_q[i] + 64'd1;
      if (i >= 3 && i < (MHPMCounterNumOut + 3))
        counter_d = counter_d & mhpmcounter_mask;
    end

    always_ff @(posedge clk_i or negedge rst_ni) begin
      if (!rst_ni)
        mhpmcounter_q[i] <= '0;
      else
        mhpmcounter_q[i] <= counter_d;
    end
  end

  // PMP CFG
  for (genvar i = 0; i < PMP_MAX_REGIONS; i++) begin : g_pmp
    always_ff @(posedge clk_i or negedge rst_ni) begin
      if (!rst_ni) begin
        pmp_cfg_q[i]  <= PMPRstCfg[i];
        pmp_addr_q[i] <= PMPRstAddr[i];
      end else if (csr_wr && PMPEnable && (i < PMPNumRegions)) begin
        if (csr_addr_i == csr_num_e'(int'(CSR_PMPCFG0) + (i / 4))) begin
          if (!pmp_cfg_q[i].lock && !mseccfg_q.rlb) begin
            automatic logic [7:0] cfg_byte;
            cfg_byte = csr_wdata_int[(i%4)*PMP_CFG_W +: PMP_CFG_W];
            pmp_cfg_q[i].lock  <= cfg_byte[7];
            pmp_cfg_q[i].mode  <= cfg_byte[4:3];
            pmp_cfg_q[i].exec  <= cfg_byte[2];
            pmp_cfg_q[i].write <= cfg_byte[1];
            pmp_cfg_q[i].read  <= cfg_byte[0];
          end
        end
        if (csr_addr_i == csr_num_e'(int'(CSR_PMPADDR0) + i)) begin
          if (!pmp_cfg_q[i].lock)
            pmp_addr_q[i] <= {csr_wdata_int[29:0], 2'b00};
        end
      end
    end
    assign csr_pmp_cfg_o[i]  = pmp_cfg_q[i];
    assign csr_pmp_addr_o[i] = pmp_addr_q[i];
  end

  // MSECCFG
  always_ff @(posedge clk_i or negedge rst_ni) begin
    if (!rst_ni) begin
      mseccfg_q <= PMPRstMsecCfg;
    end else if (csr_wr && PMPEnable && csr_addr_i == CSR_MSECCFG) begin
      if (!mseccfg_q.rlb)
        mseccfg_q.rlb <= csr_wdata_int[0];
      mseccfg_q.mmwp <= csr_wdata_int[1] | mseccfg_q.mmwp;
      mseccfg_q.mml  <= csr_wdata_int[2] | mseccfg_q.mml;
    end
  end
  assign csr_pmp_mseccfg_o = mseccfg_q;

  // DCSR
  always_ff @(posedge clk_i or negedge rst_ni) begin
    if (!rst_ni)
      dcsr_q <= 32'h4000;
    else if (debug_mode_i && csr_wr && csr_addr_i == CSR_DCSR) begin
      dcsr_q[31:28] <= csr_wdata_int[31:28];
      dcsr_q[16:15] <= csr_wdata_int[16:15];
      dcsr_q[11]    <= csr_wdata_int[11];
      dcsr_q[10:8]  <= csr_wdata_int[10:8];
      dcsr_q[5:4]   <= csr_wdata_int[5:4];
      dcsr_q[3:0]   <= csr_wdata_int[3:0];
    end
  end

  // DEPC
  always_ff @(posedge clk_i or negedge rst_ni) begin
    if (!rst_ni)
      depc_q <= '0;
    else if (debug_csr_save_i)
      depc_q <= {pc_id_i[31:1], 1'b0};
    else if (debug_mode_i && csr_wr && csr_addr_i == CSR_DPC)
      depc_q <= {csr_wdata_int[31:1], 1'b0};
  end
  assign csr_depc_o = depc_q;
  assign debug_single_step_o = dcsr_q[2];
  assign debug_ebreakm_o     = dcsr_q[15];
  assign debug_ebreaku_o      = dcsr_q[12];
  assign trigger_match_o      = 1'b0;

  // T* debug triggers
  always_ff @(posedge clk_i or negedge rst_ni) begin
    if (!rst_ni) begin
      tselect_q <= '0; tdata1_q <= '0; tdata2_q <= '0; tdata3_q <= '0;
    end else if (DbgTriggerEn) begin
      if (csr_wr && csr_addr_i == CSR_TSELECT) tselect_q <= csr_wdata_int;
      if (csr_wr && csr_addr_i == CSR_TDATA1)  tdata1_q  <= csr_wdata_int;
      if (csr_wr && csr_addr_i == CSR_TDATA2)  tdata2_q  <= csr_wdata_int;
      if (csr_wr && csr_addr_i == CSR_TDATA3)  tdata3_q  <= csr_wdata_int;
    end
  end

  // CPUCTRLSTS (custom CSR 0x7C0)
  always_ff @(posedge clk_i or negedge rst_ni) begin
    if (!rst_ni) begin
      cpuctrlsts_q <= '0;
    end else if (csr_wr && csr_addr_i == CSR_CPUCTRLSTS) begin
      if (ICache)            cpuctrlsts_q[0] <= csr_wdata_int[0];
      if (DataIndTiming)     cpuctrlsts_q[1] <= csr_wdata_int[1];
      if (DummyInstructions) cpuctrlsts_q[2] <= csr_wdata_int[2];
      cpuctrlsts_q[5:3] <= csr_wdata_int[5:3];
    end
  end
  assign icache_enable_o      = ICache ? cpuctrlsts_q[0] : 1'b0;
  assign data_ind_timing_o    = DataIndTiming ? cpuctrlsts_q[1] : 1'b0;
  assign dummy_instr_en_o     = DummyInstructions ? cpuctrlsts_q[2] : 1'b0;
  assign dummy_instr_mask_o   = cpuctrlsts_q[5:3];
  assign dummy_instr_seed_en_o = 1'b0;
  assign dummy_instr_seed_o   = '0;

  // SECURESEED
  always_ff @(posedge clk_i or negedge rst_ni) begin
    if (!rst_ni) secureseed_q <= '0;
    else if (csr_wr && csr_addr_i == CSR_SECURESEED) secureseed_q <= csr_wdata_int;
  end

  assign csr_shadow_err_o = 1'b0;
  assign double_fault_seen_o = 1'b0;

  logic cpuctrlsts_ic_scr_key_valid_q;
  always_ff @(posedge clk_i or negedge rst_ni) begin
    if (!rst_ni) cpuctrlsts_ic_scr_key_valid_q <= 1'b0;
    else cpuctrlsts_ic_scr_key_valid_q <= ic_scr_key_valid_i;
  end

endmodule

