module test_minstret;
  import ibex_pkg::*;

  logic clk, rst_n;
  logic csr_access, csr_op_en;
  csr_num_e csr_addr;
  logic [31:0] csr_wdata, csr_rdata;
  csr_op_e csr_op;
  logic illegal_csr;

  ibex_cs_registers uut (
    .clk_i(clk), .rst_ni(rst_n),
    .csr_access_i(csr_access), .csr_addr_i(csr_addr),
    .csr_wdata_i(csr_wdata), .csr_op_i(csr_op),
    .csr_op_en_i(csr_op_en), .csr_rdata_o(csr_rdata),
    .illegal_csr_insn_o(illegal_csr)
  );

