  if (ptr != intfs.end()) {
    // Send inputs to monitor
    if ((csr_access && (csr_op_en || illegal_csr)) || !rst_n) {
      ptr->second->CaptureTransaction(rst_n, illegal_csr, *csr_op, *csr_addr,
                                      *csr_rdata, *csr_wdata);
    }
  }
}

